context.handlebars.registerHelper('runtimeClock', () => {
  const frames = context.panelData?.series ?? context.panel?.panelData?.series ?? (context.dataFrame ? [context.dataFrame] : []);
  const frame = frames.find(f => f.fields?.some(field => field.type === 'number'));
  const field = frame?.fields?.find(f => f.type === 'number');
  const values = field?.values;
  const raw = values == null ? NaN : (typeof values.get === 'function' ? values.get(values.length - 1) : values[values.length - 1]);
  const seconds = Math.max(0, Math.floor(Number(raw)));
  return Number.isFinite(Number(raw)) ? `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, '0')}` : '—';
});
